import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.Bzd4OF_4.js";const h=JSON.parse('{"title":"Roadmap and progress","description":"","frontmatter":{},"headers":[],"relativePath":"roadmap.md","filePath":"roadmap.md"}'),n={name:"roadmap.md"};function d(i,t,s,l,p,c){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="roadmap-and-progress" tabindex="-1">Roadmap and progress <a class="header-anchor" href="#roadmap-and-progress" aria-label="Permalink to &quot;Roadmap and progress&quot;">​</a></h1><p>The roadmap is organized into nine milestones, from engineering foundation (M0) through full qualification (M9). Progress means acceptance criteria and evidence pass; partial percentage completion does not close a milestone.</p><h2 id="current-checkpoint-m0" tabindex="-1">Current checkpoint: M0 <a class="header-anchor" href="#current-checkpoint-m0" aria-label="Permalink to &quot;Current checkpoint: M0&quot;">​</a></h2><p>Completed foundation deliveries include the monorepo, Docker/PostgreSQL workflow, migrations and typed persistence foundations, OpenAPI workflow, shared exact-decimal finance primitives, and request fingerprint/idempotency foundations. PostgreSQL outbox/inbox and worker foundation is next.</p><h2 id="milestones" tabindex="-1">Milestones <a class="header-anchor" href="#milestones" aria-label="Permalink to &quot;Milestones&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Milestone</th><th>Outcome</th></tr></thead><tbody><tr><td>M0</td><td>Engineering foundation</td></tr><tr><td>M1</td><td>Identity and accounting configuration</td></tr><tr><td>M2</td><td>First posted journal vertical slice</td></tr><tr><td>M3</td><td>Approval and period controls</td></tr><tr><td>M4</td><td>Receivables and billing</td></tr><tr><td>M5</td><td>Payables and payment execution</td></tr><tr><td>M6</td><td>Bank and cash reconciliation</td></tr><tr><td>M7</td><td>Assets and revenue</td></tr><tr><td>M8</td><td>Currency, intercompany, and reporting</td></tr><tr><td>M9</td><td>Tax, payroll, audit, and qualification</td></tr></tbody></table><p>M2 is the recommended stopping point for a strong portfolio-sized outcome: a complete journal posting and reversal slice across domain, persistence, API, UI, authorization, tests, and operations.</p><p>See the <a href="https://github.com/toanle88/Tally/blob/main/docs/specs/finance_delivery_plan_v1.0.md" target="_blank" rel="noreferrer">delivery plan</a> and <a href="https://github.com/toanle88/Tally/blob/main/ROADMAP.md" target="_blank" rel="noreferrer">live roadmap</a> for authoritative status.</p>',8)])])}const u=e(n,[["render",d]]);export{h as __pageData,u as default};
